/** Dispatches incoming TypedEvent (typeID + body bytes) to typed handlers. */
export class TypedDispatcher {
  private handlers = new Map<number, (raw: Uint8Array) => void>();

  /** Register a handler for broadcasts of class T. The class must expose
   *  static readonly typeID and static decode(buf): T. */
  on<T>(cls: { typeID: number; decode(buf: Uint8Array): T }, fn: (msg: T) => void): () => void {
    const handler = (raw: Uint8Array) => fn(cls.decode(raw));
    this.handlers.set(cls.typeID, handler);
    return () => { if (this.handlers.get(cls.typeID) === handler) this.handlers.delete(cls.typeID); };
  }

  /** Dispatch one incoming wire event. No-op if no handler is registered for typeID. */
  dispatch(typeID: number, body: Uint8Array): void {
    const fn = this.handlers.get(typeID);
    if (fn) fn(body);
  }
}
